/* prog59_rule110.c – reproduces the behaviour of the supplied binary.
 *
 * The program expects two command‑line arguments:
 *   1. A binary string consisting only of the characters ‘0’ and ‘1’.
 *      Its length must be between 1 and 60 inclusive.
 *   2. A non‑negative integer giving the number of generations to simulate.
 *      Values larger than 200 are clamped to 200.
 *
 * The program prints the initial configuration and then the requested number
 * of generations of the elementary cellular automaton “Rule 110”.  Each
 * generation is printed on its own line.  If any of the input checks fail the
 * program prints the single line "INVALID_INPUT" (followed by a newline) and
 * terminates.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN   60      /* maximum width of the automaton */
#define MAX_STEPS 200     /* maximum number of generations */

/* Rule 110 lookup table.
 * Index = (center << 2) | (left << 1) | right
 * The table is ordered according to that index.
 *
 * 111 → 0   index 7
 * 110 → 1   index 6
 * 101 → 0   index 5
 * 100 → 1   index 4
 * 011 → 1   index 3
 * 010 → 1   index 2
 * 001 → 1   index 1
 * 000 → 0   index 0
 */
static const char RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    1, /* 100 */
    0, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

static void print_row(const char *buf, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar(buf[i]);
    putchar('\n');
}

static int is_binary_string(const char *s)
{
    for ( ; *s; ++s )
        if (*s != '0' && *s != '1')
            return 0;
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0 || len > MAX_LEN || !is_binary_string(input)) {
        puts("INVALID_INPUT");
        return 0;
    }

    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0' || steps < 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;

    char cur[MAX_LEN + 1];
    char nxt[MAX_LEN + 1];
    memcpy(cur, input, len);
    cur[len] = '\0';

    print_row(cur, len);

    for (long gen = 0; gen < steps; ++gen) {
        for (size_t i = 0; i < len; ++i) {
            int left   = (i == 0)     ? 0 : (cur[i - 1] - '0');
            int center = cur[i]      - '0';
            int right  = (i == len-1) ? 0 : (cur[i + 1] - '0');
            int index = (center << 2) | (left << 1) | right;
            nxt[i] = RULE110[index] + '0';
        }
        nxt[len] = '\0';
        print_row(nxt, len);
        memcpy(cur, nxt, len);
    }
    return 0;
}
